#include <map>
#include <string>

int main() {
    std::map<std::string, int> counts;

    // 1. Search for "apple" (misses).
    // 2. Insert {"apple", 0} (int()).
    // 3. Assign 10 to the reference.
    counts["apple"] = 10; 

    // If key exists, only assignment occurs (no new insertion).
    counts["apple"] = 11;

    // Size is 1
    return counts.size(); 
}
